"""Runtime of the code generated by all backends."""

from src.plots import generate_distribution_plot, generate_heatmap
from src.runs import Runtime

VARIANTS = ["LLVM", "Cranelift", "LLVM O1", "TPDE", "TPDE inline", "TPDE inline,promote", "TPDE MIR2", "TPDE inline MIR2", "TPDE inline,promote MIR2"]


def get_config():
    return [Runtime(VARIANTS)]


def evaluate(results):
    runs = get_config()

    generate_distribution_plot("runtime_compare_distribution",
                               "Runtime relative to LLVM -O0",
                               results, runs)

    generate_heatmap("runtime_compare_heatmap",
                     "Runtime relative to LLVM -O0",
                     results, runs)
